// Labels (docs/06a-labels.qmd): the picker (apply labels to a passage or a mark) and the Labels tab (manage,
// publish, list by chapter).
import { useMemo, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import type { LabelRow, MarkRow } from '../../../shared/types.ts'
import { sectionName } from '../../../shared/types.ts'

const COLORS = ['#43a047', '#1e88e5', '#9e9e9e', '#fb8c00', '#8e24aa', '#e53935', '#00897b', '#fdd835', '#6d4c41', '#3949ab']

export function LabelChip({ l, on, onClick, small }: { l: Pick<LabelRow, 'name' | 'color' | 'style'>; on?: boolean; onClick?: () => void; small?: boolean }) {
  const st = l.style === 'gray' ? { background: '#e5e7eb', color: '#4b5563' } : l.style === 'tint' ? { background: l.color + '33', borderColor: l.color } : { borderBottom: `3px ${l.style === 'dotted' ? 'dotted' : 'solid'} ${l.color}` }
  return (
    <button type="button" class={`chip ${on ? 'on' : ''} ${small ? 'small' : ''}`} style={st} onClick={onClick} title={l.name}>
      <span class="dot" style={{ background: l.color }} />{l.name}
    </button>
  )
}

/** Pick one or more labels; "New label…" creates and selects. */
export function LabelPicker({ s, selected, onChange, onDone, title }: { s: State; selected: string[]; onChange: (ids: string[]) => void; onDone?: () => void; title?: string }) {
  const [q, setQ] = useState('')
  const [creating, setCreating] = useState(false)
  const [name, setName] = useState('')
  const [color, setColor] = useState(COLORS[0])
  const [kind, setKind] = useState<'coverage' | 'plain'>(s.staffIds.length ? 'coverage' : 'plain')
  const uid = s.session?.user.id
  const infos = useMemo(() => store.labelInfos(), [s.labels, s.recentLabels])
  const list = infos.filter((l) => !q || l.name.toLowerCase().includes(q.toLowerCase()))
  const mine = list.filter((l) => l.mine)
  const theirs = list.filter((l) => !l.mine)
  const toggle = (id: string) => onChange(selected.includes(id) ? selected.filter((x) => x !== id) : [...selected, id])
  const create = async () => {
    if (!name.trim()) return
    const row = await store.createLabel({ name: name.trim(), color, kind, style: 'tint' })
    if (row) {
      onChange([...selected, row.id])
      setCreating(false)
      setName('')
    }
  }
  return (
    <div class="picker">
      {title && <div class="small muted">{title}</div>}
      <input type="search" placeholder="Find a label…" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} autoFocus />
      <div class="chips">
        {mine.map((l) => <LabelChip key={l.id} l={l} on={selected.includes(l.id)} onClick={() => toggle(l.id)} />)}
      </div>
      {theirs.length > 0 && (
        <>
          <div class="small muted">Published to you</div>
          <div class="chips">{theirs.map((l) => <LabelChip key={l.id} l={l} on={selected.includes(l.id)} onClick={() => toggle(l.id)} />)}</div>
        </>
      )}
      {!creating ? (
        <button class="link small" onClick={() => { setCreating(true); setName(q) }}>+ New label…</button>
      ) : (
        <div class="newlabel">
          <input placeholder="Label name" value={name} onInput={(e) => setName((e.target as HTMLInputElement).value)} onKeyDown={(e) => { if (e.key === 'Enter') create() }} autoFocus />
          <div class="row">
            {COLORS.map((c) => <button key={c} type="button" class={`swatch ${color === c ? 'on' : ''}`} style={{ background: c }} onClick={() => setColor(c)} aria-label={c} />)}
          </div>
          {s.staffIds.length > 0 && (
            <label class="chk"><input type="checkbox" checked={kind === 'coverage'} onChange={(e) => setKind((e.target as HTMLInputElement).checked ? 'coverage' : 'plain')} /> Counts as class coverage (filed under the meeting; in "What we covered")</label>
          )}
          <div class="row"><button class="small primary" onClick={create} disabled={!name.trim() || s.busy}>Create</button><button class="small" onClick={() => setCreating(false)}>Cancel</button></div>
        </div>
      )}
      {onDone && <div class="row"><button class="primary" disabled={!selected.length || s.busy} onClick={onDone}>Apply {selected.length ? `(${selected.length})` : ''}</button><button onClick={() => store.cancelPending()}>Cancel</button></div>}
      {uid && <div class="muted small">Labels you make are private until you publish them (Labels tab).</div>}
    </div>
  )
}

/** The Labels tab. */
export function Labels({ s }: { s: State }) {
  const uid = s.session?.user.id
  const [editing, setEditing] = useState<string | null>(null)
  if (!s.session) return <div class="muted pad">Sign in to make labels. Labels your instructor published show on the page and in the listing.</div>
  const countOnPage = (id: string) => s.marks.filter((m) => ((m.data.labels as string[]) || []).includes(id)).length
  const mine = s.labels.filter((l) => l.owner_id === uid)
  const theirs = s.labels.filter((l) => l.owner_id !== uid)
  const listUrl = (l: LabelRow) => `${location.origin}/covered/?section=${encodeURIComponent(s.section?.slug || s.sections.find((x) => s.teachSections.includes(x.id))?.slug || '')}&label=${encodeURIComponent(l.name)}`
  return (
    <div class="labels">
      <div class="row">
        <button class="small primary" disabled={s.busy} onClick={() => { store.openPanel(false); void store.sendToc(true) }}>Table of contents by label</button>
        <span class="muted small">every labeled place in the whole book, with links (also at the top of the book's sidebar)</span>
      </div>
      <div class="row"><strong>My labels</strong> <span class="muted small">click a name to edit</span></div>
      {mine.map((l) => (
        <div key={l.id} class="labelrow">
          <div class="row">
            <LabelChip l={l} on={s.currentLabel === l.id} onClick={() => store.setCurrentLabel(l.id)} />
            <span class="muted small">{countOnPage(l.id)} on this page{l.kind === 'coverage' ? ' · coverage' : ''}</span>
            <button class="link small" onClick={() => setEditing(editing === l.id ? null : l.id)}>{editing === l.id ? 'close' : 'edit'}</button>
            <a class="small" href={listUrl(l)} target="_blank" rel="noopener">list ↗</a>
          </div>
          {editing === l.id && <LabelEditor s={s} l={l} onClose={() => setEditing(null)} />}
        </div>
      ))}
      {theirs.length > 0 && (
        <>
          <div class="row"><strong>Published to you</strong></div>
          {theirs.map((l) => (
            <div key={l.id} class="labelrow row">
              <LabelChip l={l} /> <span class="muted small">{countOnPage(l.id)} on this page</span> <a class="small" href={listUrl(l)} target="_blank" rel="noopener">list ↗</a>
            </div>
          ))}
        </>
      )}
      <div class="muted small">The current label (highlighted) is applied with the L key while a passage is selected.</div>
    </div>
  )
}

function LabelEditor({ s, l, onClose }: { s: State; l: LabelRow; onClose: () => void }) {
  const [name, setName] = useState(l.name)
  const [color, setColor] = useState(l.color)
  const [style, setStyle] = useState<LabelRow['style']>(l.style)
  const [kind, setKind] = useState<LabelRow['kind']>(l.kind)
  const [pub, setPub] = useState<string[]>(l.visibility === 'sections' ? l.sections : [])
  const mySections = s.sections.filter((x) => s.staffIds.includes(x.id) || s.enrolledIds.includes(x.id))
  const save = async () => {
    await store.updateLabel(l.id, { name: name.trim() || l.name, color, style, kind, visibility: pub.length ? 'sections' : 'private', sections: pub })
    onClose()
  }
  return (
    <div class="card">
      <label>Name <input value={name} onInput={(e) => setName((e.target as HTMLInputElement).value)} /></label>
      <div class="row">{COLORS.map((c) => <button key={c} type="button" class={`swatch ${color === c ? 'on' : ''}`} style={{ background: c }} onClick={() => setColor(c)} aria-label={c} />)}</div>
      <div class="row">
        <span class="lbl">Style</span>
        {(['tint', 'underline', 'dotted', 'gray'] as const).map((x) => <label key={x} class="chk"><input type="radio" checked={style === x} onChange={() => setStyle(x)} /> {x}</label>)}
      </div>
      {s.staffIds.length > 0 && <label class="chk"><input type="checkbox" checked={kind === 'coverage'} onChange={(e) => setKind((e.target as HTMLInputElement).checked ? 'coverage' : 'plain')} /> Counts as class coverage</label>}
      <div class="row">
        <span class="lbl">Published to</span>
        {mySections.length ? mySections.map((x) => (
          <label key={x.id} class="chk"><input type="checkbox" checked={pub.includes(x.id)} onChange={(e) => setPub((e.target as HTMLInputElement).checked ? [...pub, x.id] : pub.filter((id) => id !== x.id))} /> {sectionName(x)}</label>
        )) : <span class="muted small">no sections</span>}
      </div>
      <div class="row">
        <button class="small primary" onClick={save}>Save</button>
        <button class="small" onClick={onClose}>Cancel</button>
        <button class="small danger" onClick={() => { const a = prompt(`Delete "${l.name}". Type KEEP to keep its marks without the label, DELETE to delete the marks too, or cancel.`); if (a === 'KEEP') store.deleteLabel(l.id, 'keep'); else if (a === 'DELETE') store.deleteLabel(l.id, 'delete') }}>Delete…</button>
      </div>
    </div>
  )
}

/** Inline label change on a mark card. */
export function MarkLabels({ s, m }: { s: State; m: MarkRow }) {
  const [open, setOpen] = useState(false)
  const ids = (m.data.labels as string[]) || []
  const byId = new Map(s.labels.map((l) => [l.id, l]))
  return (
    <div>
      <div class="chips">{ids.map((id) => byId.get(id)).filter(Boolean).map((l) => <LabelChip key={l!.id} l={l!} small />)}
        {m.author_id === s.session?.user.id && <button class="link small" onClick={() => setOpen(!open)}>{open ? 'done' : 'change'}</button>}
      </div>
      {open && <LabelPicker s={s} selected={ids} onChange={(next) => store.setMarkLabels(m, next)} />}
    </div>
  )
}
