// Staff: the section's tutor settings and usage (docs/08-ai-tutor.qmd). Students: their own API key.
import { useEffect, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import * as api from '../api.ts'
import { getStudentKey, setStudentKey } from '../features/tutor.ts'
import type { SectionRow } from '../../../shared/types.ts'

export function SectionAiSettings({ s, section }: { s: State; section: SectionRow }) {
  const ai = (section.ai || {}) as { mode?: string; daily_limit?: number; monthly_cap_usd?: number; instructions?: string; staff_view?: string }
  const [form, setForm] = useState({ mode: ai.mode || 'off', daily_limit: ai.daily_limit ?? 125, monthly_cap_usd: ai.monthly_cap_usd ?? 20, instructions: ai.instructions || '', staff_view: ai.staff_view || 'aggregate' })
  const [usage, setUsage] = useState<Array<{ month: string; messages: number; cost_usd: number }> | null>(null)
  useEffect(() => { api.aiUsage(section.id).then(setUsage).catch(() => setUsage([])) }, [section.id])
  const up = (k: string, v: unknown) => setForm({ ...form, [k]: v })
  return (
    <div class="card ai-settings">
      <div><strong>✦ Tutor · section {section.label}</strong></div>
      <label>Mode
        <select value={form.mode} onChange={(e) => up('mode', (e.target as HTMLSelectElement).value)}>
          <option value="off">off (no Ask button)</option>
          <option value="instructor">instructor pays (your API key on the server)</option>
          <option value="student">students use their own keys</option>
          <option value="either">instructor pays within limits, then students' keys</option>
        </select>
      </label>
      <div class="row">
        <label>Questions per student per day <input type="number" min={1} value={form.daily_limit} onInput={(e) => up('daily_limit', Number((e.target as HTMLInputElement).value))} /></label>
        <label>Monthly cap (USD) <input type="number" min={0} value={form.monthly_cap_usd} onInput={(e) => up('monthly_cap_usd', Number((e.target as HTMLInputElement).value))} /></label>
      </div>
      <label>Instructions to the tutor for this section
        <textarea value={form.instructions} placeholder="e.g. Students are business majors new to programming. Don't write code for them." onInput={(e) => up('instructions', (e.target as HTMLTextAreaElement).value)} />
      </label>
      <label>What staff see of conversations
        <select value={form.staff_view} onChange={(e) => up('staff_view', (e.target as HTMLSelectElement).value)}>
          <option value="aggregate">counts per passage only</option>
          <option value="full">full conversations</option>
          <option value="none">nothing</option>
        </select>
      </label>
      <div class="row">
        <button class="small" onClick={() => store.setSectionAi(section.id, { ...ai, ...form })}>Save</button>
        {usage && <span class="muted small">{usage.length ? usage.map((u) => `${String(u.month).slice(0, 7)}: ${u.messages} msgs, $${Number(u.cost_usd).toFixed(2)}`).join(' · ') : 'no usage yet'}</span>}
      </div>
    </div>
  )
}

export function StudentKey() {
  const [key, setKey] = useState(getStudentKey() || '')
  const [remember, setRemember] = useState(false)
  const [saved, setSaved] = useState(!!getStudentKey())
  return (
    <div class="card">
      <div><strong>Your own AI key</strong> <span class="muted small">(only if your section uses student keys)</span></div>
      <div class="muted small">A pay-as-you-go Anthropic API key from console.anthropic.com (a Claude Pro subscription doesn't include one). Set a monthly spending limit on it. The key is kept only in this panel's storage on subjexts.github.io and is sent only to Anthropic.</div>
      <input type="password" placeholder="sk-ant-…" value={key} onInput={(e) => { setKey((e.target as HTMLInputElement).value); setSaved(false) }} />
      <label class="chk"><input type="checkbox" checked={remember} onChange={(e) => setRemember((e.target as HTMLInputElement).checked)} /> Remember on this device (otherwise forgotten when the tab closes)</label>
      <div class="row">
        <button class="small" onClick={() => { setStudentKey(key.trim() || null, remember); setSaved(true) }}>{key.trim() ? 'Save key' : 'Forget key'}</button>
        {saved && <span class="muted small">{key.trim() ? 'saved' : 'forgotten'}</span>}
      </div>
    </div>
  )
}
