import { useState } from 'preact/hooks'
import { sectionName } from '../../../shared/types.ts'
import { store, type State, VERSION } from '../store.ts'
import * as api from '../api.ts'
import { SignIn } from './SignIn.tsx'
import { SectionPicker } from './PageMarks.tsx'
import { StudentKey } from './AiSettings.tsx'

export function Settings({ s }: { s: State }) {
  const [handle, setHandle] = useState(s.profile?.handle || '')
  const [name, setName] = useState(s.profile?.display_name || '')
  const [msg, setMsg] = useState<string | null>(null)
  const [code, setCode] = useState('')
  const [req, setReq] = useState({ school: '', course: '', note: '' })
  const [reqSent, setReqSent] = useState(false)
  const save = async () => {
    try {
      await api.updateProfile({ display_name: name.trim() || s.profile?.display_name, handle: handle.trim() || null })
      setMsg('Saved')
    } catch (e) {
      setMsg(String(e))
    }
  }
  const coveredUrl = s.section ? `${location.origin}/covered/?section=${encodeURIComponent(s.section.slug)}` : null
  return (
    <div class="settings">
      <SignIn s={s} />
      <SectionPicker s={s} />
      {s.session && !s.staffIds.length && (
        <div class="card">
          <div><strong>Join your section</strong> <span class="muted small">(needed to message your instructor)</span></div>
          <div class="row">
            <input placeholder="join code from your instructor" value={code} onInput={(e) => setCode((e.target as HTMLInputElement).value)} />
            <button class="small" disabled={!code.trim() || s.busy} onClick={() => store.joinSection(code)}>Join</button>
          </div>
          {s.enrolledIds.length > 0 && <div class="muted small">Joined: {s.sections.filter((x) => s.enrolledIds.includes(x.id)).map((x) => sectionName(x)).join(', ') || `${s.enrolledIds.length} section(s)`}</div>}
        </div>
      )}
      {s.session && s.profile?.role === 'student' && (
        <div class="card">
          <div><strong>I'm an instructor</strong> <span class="muted small">(an admin approves requests)</span></div>
          {reqSent ? <div class="muted small">Request sent.</div> : (
            <>
              <label>School <input value={req.school} onInput={(e) => setReq({ ...req, school: (e.target as HTMLInputElement).value })} /></label>
              <label>Course(s) you teach <input value={req.course} onInput={(e) => setReq({ ...req, course: (e.target as HTMLInputElement).value })} /></label>
              <label>Anything else <input value={req.note} onInput={(e) => setReq({ ...req, note: (e.target as HTMLInputElement).value })} /></label>
              <button class="small" disabled={!req.school.trim()} onClick={() => api.requestInstructor(req).then(() => setReqSent(true)).catch((e) => setMsg(String(e)))}>Send request</button>
            </>
          )}
        </div>
      )}
      {s.session && !s.staffIds.length && <StudentKey />}
      {coveredUrl && <p><a href={coveredUrl} target="_blank" rel="noopener">What we covered: {sectionName(s.section!)} ↗</a></p>}
      {s.session && s.profile && (
        <div class="card">
          <div><strong>Your profile</strong></div>
          <label>Display name <input value={name} onInput={(e) => setName((e.target as HTMLInputElement).value)} /></label>
          <label>Handle <input value={handle} placeholder="lower-case, letters, digits, dashes" onInput={(e) => setHandle((e.target as HTMLInputElement).value)} /></label>
          <div class="muted small">The handle is the owner part of packages you create (handle/name).</div>
          <button class="small" onClick={save}>Save</button> {msg && <span class="muted small">{msg}</span>}
        </div>
      )}
      <div class="card muted small">
        <div>What this shows: your instructor's coverage marks and comments for the section you chose. Stored: your sign-in name and email, and what you write (notes, comments). Nothing else is tracked.</div>
        <div>subjexts · {VERSION} · package {s.pkg?.slug} · build {s.build?.id || 'none'}</div>
      </div>
    </div>
  )
}
